-- Replace {NO} with the document number (e.g. AA26…). Mapping verified: yes — SIT 2026-11-23: PM_WORKFLOW_STATUS CP/MR doc_id = PM_ACCESS_APPL.ACCESS_APPL_ID (230/233, 270/273); AP180116000000162 → CP 75005, MR 75000. Flow: claude-skills memory reference-pm-access-application-flow

-- Status history (CP); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pm_workflow_status w
 where w.doc_type = 'CP'
   and w.doc_id in (select access_appl_id from ngep_sit.pm_access_appl where appl_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Status history (MR); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pm_workflow_status w
 where w.doc_type = 'MR'
   and w.doc_id in (select access_appl_id from ngep_sit.pm_access_appl where appl_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Open BPM tasks: who the task is assigned to (task name = activityname)
select activityname, state, assignees, acquiredby, to_char(createddate, 'YYYY-MM-DD HH24:MI:SS') as created
  from SIT01_SOAINFRA.wftask@SITSOA
 where customattributestring1 = '{NO}'
 order by createddate;

-- Every status a CP has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pm_workflow_status w
 where w.doc_type = 'CP' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;

-- Every status a MR has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pm_workflow_status w
 where w.doc_type = 'MR' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;
